test('invoiceTotals calculates subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 2 * 8500 + 5 * 980;
  const line1Discount = 425;
  const line2Discount = 122;
  const discount = line1Discount + line2Discount;
  const line1VAT = 3625;
  const line2VAT = 178;
  const vat = line1VAT + line2VAT;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

